/* Govstack local HTMX shim.
 *
 * The current templates only need the script tag to resolve cleanly. This
 * stub keeps the shell functional without introducing a broken 404 while the
 * app remains progressively enhanced elsewhere.
 */
(function (global) {
  if (global.htmx) {
    return;
  }

  global.htmx = {
    config: {},
    version: "0.0.0-govstack-shim",
    on: function () {},
    off: function () {},
    trigger: function () {},
    process: function () {},
    ajax: function () {
      return Promise.resolve();
    },
  };
})(window);
